34	/**
35	 * Check whether an opaque content part is a StatefulMarkerContainer and retrieve the stateful marker if so
36	 */
37	export function rawPartAsStatefulMarker(part: Raw.ChatCompletionContentPartOpaque): StatefulMarkerWithModel | undefined {
38		const value = part.value;
39		if (!value || typeof value !== 'object') {
40			return;
41		}
42	
43		const data = value as IStatefulMarkerContainer;
44		if (data.type === CustomDataPartMimeTypes.StatefulMarker && typeof data.value === 'object') {
45			return data.value;
46		}
47		return;
48	}
