50	export function encodeStatefulMarker(modelId: string, marker: string): Uint8Array {
51		return new TextEncoder().encode(modelId + '\\' + marker);
52	}
53	
54	export function decodeStatefulMarker(data: Uint8Array): StatefulMarkerWithModel {
55		const decoded = new TextDecoder().decode(data);
56		const [modelId, marker] = decoded.split('\\');
57		return { modelId, marker };
58	}
