87	/**
88	 * Finds the message index of a specific stateful marker value in the message history.
89	 * Returns the index if found, undefined otherwise.
90	 */
91	export function getIndexOfStatefulMarker(markerValue: string, messages: readonly Raw.ChatMessage[]): number | undefined {
92		for (const entry of getAllStatefulMarkersAndIndicies(messages)) {
93			if (entry.statefulMarker.marker === markerValue) {
94				return entry.index;
95			}
96		}
97		return undefined;
98	}
